fn association(){
let raw:[u8;8]=kani::any();let len:usize=kani::any();kani::assume(len<=8);let r=token_array::<8>(&raw[..len]);
let mut observed=r;if let Ok(ref mut a)=observed{a[0]^=1;}if len!=8{assert!(observed==Err(ProgramError::Custom(0x4153_2015)));}else{let j:usize=kani::any();kani::assume(j<8);assert!(observed.unwrap()[j]==raw[j]);}

}
